// Usage: node probe.mjs <baseUrl> <outDir>
// Requests each page under several cookie scenarios and writes status/location/body to outDir.
import { mkdirSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'

const [base, outDir] = process.argv.slice(2)
mkdirSync(outDir, { recursive: true })

const enc = v => encodeURIComponent(JSON.stringify(v))
const scenarios = {
  anon: '',
  cart: `cart=${enc([{ slug: 'notebook', qty: 2 }, { slug: 'stapler', qty: 1 }])}`,
  cartDiscount: `cart=${enc([{ slug: 'notebook', qty: 2 }, { slug: 'stapler', qty: 1 }])}; discount-code=${encodeURIComponent('SAVE10')}`,
  discountOnly: `discount-code=${encodeURIComponent('HALF')}`,
}
const pages = ['/', '/cart', '/checkout', '/products/notebook', '/products/pencil']

const summary = []
for (const [sName, cookie] of Object.entries(scenarios)) {
  for (const page of pages) {
    const res = await fetch(base + page, { redirect: 'manual', headers: cookie ? { cookie } : {} })
    const body = await res.text()
    const name = `${sName}${page.replace(/\//g, '_') || '_root'}`
    writeFileSync(join(outDir, `${name}.html`), body)
    summary.push(`${sName.padEnd(13)} ${page.padEnd(20)} ${res.status} location=${res.headers.get('location') ?? '-'}`)
  }
}
writeFileSync(join(outDir, 'summary.txt'), summary.join('\n') + '\n')
console.log(summary.join('\n'))

export default defineNuxtConfig({
  // The cart layer goes first so its `useCart` overrides the base layer's legacy one.
  extends: ['./layers/cart'],
  compatibilityDate: '2026-01-01',
  devtools: { enabled: false },
  telemetry: false,
})
